{"implementation":"def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])
    node_map = {n["id"]: n for n in nodes}
    keep_ids = set()
    for n in nodes:
        if not n["removable"]:
            keep_ids.add(n["id"])
    need_symbols = required_symbols.copy()
    for nid in keep_ids:
        sym = node_map[nid]["symbol"]
        need_symbols.discard(sym)
    added_ids = set()
    for sym in need_symbols:
        candidates = [n for n in nodes if n["symbol"] == sym and n["id"] not in keep_ids]
        if candidates:
            chosen = candidates[0]
            cur = chosen["id"]
            while cur is not None:
                if cur not in keep_ids and cur not in added_ids:
                    added_ids.add(cur)
                cur = node_map[cur]["parent"]
    keep_ids |= added_ids
    changed = True
    while changed:
        changed = False
        for nid in list(keep_ids):
            parent_id = node_map[nid]["parent"]
            if parent_id is not None and parent_id not in keep_ids:
                keep_ids.add(parent_id)
                changed = True
    result_nodes = [node_map[nid] for nid in keep_ids]
    return {"nodes": result_nodes}"}
